-- Rookie Bakery data 2026-11-20T15:58:32.534Z
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
DROP TABLE IF EXISTS "users";
CREATE TABLE users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,phone TEXT UNIQUE NOT NULL,address TEXT NOT NULL DEFAULT '',password TEXT NOT NULL, locked INTEGER NOT NULL DEFAULT 0);
DROP TABLE IF EXISTS "cart";
CREATE TABLE cart(user_id TEXT REFERENCES users(id),product_id INTEGER REFERENCES products(id),qty INTEGER NOT NULL CHECK(qty>0),PRIMARY KEY(user_id,product_id));
DROP TABLE IF EXISTS "favorites";
CREATE TABLE favorites(user_id TEXT REFERENCES users(id),product_id INTEGER REFERENCES products(id),PRIMARY KEY(user_id,product_id));
DROP TABLE IF EXISTS "orders";
CREATE TABLE orders(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),created TEXT NOT NULL,status TEXT NOT NULL,payment TEXT NOT NULL,payment_status TEXT NOT NULL,shipping TEXT NOT NULL,subtotal INTEGER NOT NULL,fee INTEGER NOT NULL,total INTEGER NOT NULL,request_key TEXT NOT NULL,UNIQUE(user_id,request_key));
DROP TABLE IF EXISTS "order_events";
CREATE TABLE order_events(id INTEGER PRIMARY KEY,order_id TEXT REFERENCES orders(id),status TEXT NOT NULL,created TEXT NOT NULL);
DROP TABLE IF EXISTS "reviews";
CREATE TABLE reviews(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),product_id INTEGER REFERENCES products(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),content TEXT NOT NULL,created TEXT NOT NULL,reply TEXT,UNIQUE(user_id,product_id));
DROP TABLE IF EXISTS "payment_attempts";
CREATE TABLE payment_attempts(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),data TEXT NOT NULL,status TEXT NOT NULL,expires INTEGER NOT NULL,request_key TEXT NOT NULL,UNIQUE(user_id,request_key));
DROP TABLE IF EXISTS "staff";
CREATE TABLE staff(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,phone TEXT NOT NULL DEFAULT '',role TEXT NOT NULL CHECK(role IN ('admin','staff')),perms TEXT NOT NULL DEFAULT '[]',password TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created TEXT NOT NULL);
