DROP TABLE IF EXISTS "categories";
CREATE TABLE categories(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,description TEXT NOT NULL DEFAULT '');
INSERT INTO "categories"(id,name,description) VALUES(1,'Bánh kem','');
INSERT INTO "categories"(id,name,description) VALUES(2,'Bánh ngọt','');
INSERT INTO "categories"(id,name,description) VALUES(3,'Bánh nướng','');
DROP TABLE IF EXISTS "settings";
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
DROP TABLE IF EXISTS "order_items";
CREATE TABLE order_items(order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,line INTEGER NOT NULL,product_id INTEGER REFERENCES products(id) ON DELETE SET NULL,name TEXT NOT NULL,type TEXT NOT NULL DEFAULT '',img TEXT NOT NULL DEFAULT '',price INTEGER NOT NULL CHECK(price>=0),qty INTEGER NOT NULL CHECK(qty>0),PRIMARY KEY(order_id,line));
DROP TABLE IF EXISTS "purchases";
CREATE TABLE purchases(id TEXT PRIMARY KEY,created TEXT NOT NULL,staff TEXT NOT NULL,supplier TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',total INTEGER NOT NULL CHECK(total>=0));
DROP TABLE IF EXISTS "purchase_items";
CREATE TABLE purchase_items(purchase_id TEXT NOT NULL REFERENCES purchases(id) ON DELETE CASCADE,line INTEGER NOT NULL,product_id INTEGER REFERENCES products(id) ON DELETE SET NULL,name TEXT NOT NULL,qty INTEGER NOT NULL CHECK(qty>0),cost INTEGER NOT NULL CHECK(cost>=0),PRIMARY KEY(purchase_id,line));
DROP TABLE IF EXISTS "products";
CREATE TABLE "products"(id INTEGER PRIMARY KEY,category_id INTEGER NOT NULL REFERENCES categories(id),name TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',ingredients TEXT NOT NULL DEFAULT '',allergens TEXT NOT NULL DEFAULT '',storage TEXT NOT NULL DEFAULT '',price INTEGER NOT NULL CHECK(price>=0),img TEXT NOT NULL DEFAULT 'cake.jpg',stock INTEGER NOT NULL CHECK(stock>=0),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
INSERT INTO "products"(id,category_id,name,note,description,ingredients,allergens,storage,price,img,stock,active) VALUES(1,1,'Strawberry little love','Dâu tươi · kem vanilla · một chút yêu','Bánh kem dâu với cốt bông lan mềm, kem vanilla và dâu tươi. Một chiếc bánh dịu dàng cho những dịp đặc biệt.','Bột mì, trứng, sữa, bơ, kem sữa, dâu tươi','Có gluten, trứng và sữa.','Bảo quản lạnh 2–6°C, dùng trong 24 giờ.',185000,'berry.jpg',20,1);
INSERT INTO "products"(id,category_id,name,note,description,ingredients,allergens,storage,price,img,stock,active) VALUES(2,1,'Chocolate daydream','Chocolate đậm · mềm tan · thật chiều lòng','Cốt bánh chocolate mềm phủ ganache đậm vị, trang trí trái cây. Dành cho những người yêu vị cacao nguyên bản.','Bột mì, trứng, bơ, chocolate, kem sữa, trái cây','Có gluten, trứng, sữa; có thể chứa hạt.','Bảo quản lạnh 2–6°C, dùng trong 24 giờ.',225000,'hero.jpg',15,1);
INSERT INTO "products"(id,category_id,name,note,description,ingredients,allergens,storage,price,img,stock,active) VALUES(3,2,'A slice of sunshine','Cốt bánh mềm · kem tươi · nắng dịu dàng','Một phần bánh vanilla nhiều lớp với kem tươi và sốt quả mọng. Vừa đủ ngọt cho giờ trà chiều.','Bột mì, trứng, sữa, kem tươi, vanilla, quả mọng','Có gluten, trứng và sữa.','Bảo quản lạnh 2–6°C, dùng trong 24 giờ.',65000,'cake.jpg',30,1);
INSERT INTO "products"(id,category_id,name,note,description,ingredients,allergens,storage,price,img,stock,active) VALUES(4,3,'Bonjour, sweet morning','Bánh nướng thơm · trái cây · buổi sáng chậm','Bánh ngàn lớp bơ thơm, nướng vàng giòn mỗi sáng, ăn kèm trái cây theo mùa.','Bột mì, bơ, sữa, trứng, men, trái cây','Có gluten, trứng và sữa.','Dùng trong ngày; có thể hâm nóng nhẹ trước khi ăn.',75000,'toast.jpg',25,1);
COMMIT;
